// Stage 3/4 -- 24h lawyer nudge (Section 5, bullet 5). This is the Schedule
// Trigger half of the Stage 3/4 workflow; the Webhook half (draft invoice,
// approvals, lawyer draft handling) lives in stage3-4-action-code.js.

const helpers = this.helpers;
const env = {
  SUPABASE_URL: $env.SUPABASE_URL,
  SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY,
  META_TOKEN: $env.META_ACCESS_TOKEN,
  META_PHONE_ID: $env.META_PHONE_NUMBER_ID,
};

const sbHeaders = {
  apikey: env.SUPABASE_KEY,
  Authorization: `Bearer ${env.SUPABASE_KEY}`,
  'Content-Type': 'application/json',
};

async function sbRequest(method, path, body, extraHeaders) {
  return helpers.httpRequest({
    method,
    url: `${env.SUPABASE_URL}/rest/v1/${path}`,
    headers: { ...sbHeaders, ...(extraHeaders || {}) },
    body,
    json: true,
    timeout: 15000,
  });
}

async function sbPatch(path, body) {
  return sbRequest('PATCH', path, body, { Prefer: 'return=representation' });
}

// Sandbox mode: on when there's no real Meta token configured (the sandbox
// n8n instance is deliberately deployed without one, so it's structurally
// incapable of reaching real WhatsApp, not just told not to). Every outbound
// send is captured in `sandbox_outbound` instead, for the test webpage to
// display, and a fake message id stands in for the real one.
const SANDBOX = !env.META_TOKEN;
async function sandboxLog(toNumber, text, kind) {
  const messageId = `sandbox-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  try {
    await sbRequest('POST', 'sandbox_outbound', { to_number: toNumber, kind: kind || 'text', message_text: text, message_id: messageId });
  } catch (e) {}
  return messageId;
}

function sanitizeTemplateParam(text) {
  return String(text || '')
    .replace(/[\r\n]+/g, ' -- ')
    .replace(/\s{2,}/g, ' ')
    .trim()
    .slice(0, 1000) || '(see details)';
}

// A daily scheduled nudge almost never lands inside the lawyer's 24h window --
// fall back to the approved "bali_update" utility template whenever the
// free-form send is rejected with error 131047.
//
// Owner's explicit correction (2026-08-03): this used to stuff the ENTIRE
// message text into the template's one body variable. shortLabel is now a
// short description instead (an event name, or a generic fallback) -- the
// real content always follows as a genuine, unmodified send in sendWhatsApp
// below.
async function sendWhatsAppTemplate(toNumber, shortLabel) {
  if (SANDBOX) return sandboxLog(toNumber, shortLabel, 'template');
  const res = await helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v20.0/${env.META_PHONE_ID}/messages`,
    headers: { Authorization: `Bearer ${env.META_TOKEN}`, 'Content-Type': 'application/json' },
    body: {
      messaging_product: 'whatsapp',
      to: toNumber,
      type: 'template',
      template: {
        name: 'bali_update',
        language: { code: 'en_US' },
        components: [{ type: 'body', parameters: [{ type: 'text', text: sanitizeTemplateParam(shortLabel) }] }],
      },
    },
    json: true,
    timeout: 20000,
  });
  return res?.messages?.[0]?.id || null;
}

// Confirmed live: a direct text send to a contact whose last inbound message
// was well over 24h old returned 200 with a real message id from Meta, but
// never actually delivered -- outside the messaging window, Meta accepts the
// call and silently drops it instead of rejecting it synchronously with
// 131047 (delivery failure only shows up later via a status webhook we don't
// listen for). Catching 131047 reactively therefore doesn't reliably work.
// Check the window proactively instead, from the contact's own last inbound
// message, and go straight to the template when it's closed.
async function isWithinMessagingWindow(toNumber) {
  const contacts = await sbRequest('GET', `contacts?phone_number=eq.${encodeURIComponent(toNumber)}&select=id`);
  const contactId = contacts[0]?.id;
  if (!contactId) return false;
  const rows = await sbRequest(
    'GET',
    `conversations?sender_contact_id=eq.${contactId}&direction=eq.inbound&select=created_at&order=created_at.desc&limit=1`
  );
  if (!rows[0]) return false;
  const hoursSinceLastInbound = (Date.now() - new Date(rows[0].created_at).getTime()) / (1000 * 60 * 60);
  return hoursSinceLastInbound < 23; // stay a safety margin under the real 24h cutoff
}

async function sendRawText(toNumber, text) {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v20.0/${env.META_PHONE_ID}/messages`,
    headers: { Authorization: `Bearer ${env.META_TOKEN}`, 'Content-Type': 'application/json' },
    body: { messaging_product: 'whatsapp', to: toNumber, type: 'text', text: { body: text } },
    json: true,
    timeout: 20000,
  });
  return res?.messages?.[0]?.id || null;
}

// Owner's explicit correction (2026-08-03): don't attempt the real content
// right behind the template anymore -- see stage1-code.js's version for the
// full explanation. Park it and wait for real proof the window's open. This
// file only ever sends to the lawyer, who flushes their queue via
// stage3-4-action-code.js's handleLawyerInbound the next time they message.
async function queueMessage(toNumber, text) {
  await sbRequest('POST', 'queued_messages', { phone_number: toNumber, message_text: text });
}

// shortLabel: see sendWhatsAppTemplate above.
async function sendWhatsApp(toNumber, text, shortLabel) {
  if (SANDBOX) return sandboxLog(toNumber, text, 'text');
  if (!(await isWithinMessagingWindow(toNumber))) {
    await sendWhatsAppTemplate(toNumber, shortLabel || 'an update');
    await queueMessage(toNumber, text);
    return null;
  }
  try {
    return await sendRawText(toNumber, text);
  } catch (err) {
    let errStr;
    try { errStr = JSON.stringify(err, Object.getOwnPropertyNames(err)); } catch (e) { errStr = String(err); }
    errStr += JSON.stringify(err?.response?.data || err?.response?.body || '');
    if (errStr.includes('131047')) {
      await sendWhatsAppTemplate(toNumber, shortLabel || 'an update');
      await queueMessage(toNumber, text);
      return null;
    }
    throw err;
  }
}

const DAY_MS = 24 * 60 * 60 * 1000;

const lawyer = (await sbRequest('GET', 'contacts?role=eq.lawyer&select=*&limit=1'))[0];
if (!lawyer) {
  return [{ json: { skipped: true, reason: 'no lawyer contact configured yet' } }];
}

const waiting = await sbRequest('GET', 'bookings?status=eq.awaiting_contract&select=*');
let nudged = 0;

for (const booking of waiting) {
  const last = booking.last_lawyer_nudge_at ? new Date(booking.last_lawyer_nudge_at).getTime() : 0;
  if (Date.now() - last >= DAY_MS) {
    await sendWhatsApp(lawyer.phone_number, `Reminder: still waiting on the contract draft for ${booking.event_name} (event date ${booking.event_date || 'TBD'}).`, booking.event_name);
    await sbPatch(`bookings?id=eq.${booking.id}`, { last_lawyer_nudge_at: new Date().toISOString() });
    nudged += 1;
  }
}

return [{ json: { checked: waiting.length, nudged } }];

// Stage 3 (Invoice) & Stage 4 (Contract) -- real implementation.
// Single webhook handles several actions (discriminated by input.action),
// mirroring the pattern used by 04-kb-check.json.

const helpers = this.helpers;
const env = {
  SUPABASE_URL: $env.SUPABASE_URL,
  SUPABASE_KEY: $env.SUPABASE_SERVICE_KEY,
  OPENAI_KEY: $env.OPENAI_API_KEY,
  META_TOKEN: $env.META_ACCESS_TOKEN,
  META_PHONE_ID: $env.META_PHONE_NUMBER_ID,
  GOTENBERG_URL: $env.GOTENBERG_URL,
  N8N_BASE_URL: $env.N8N_BASE_URL,
};

const sbHeaders = {
  apikey: env.SUPABASE_KEY,
  Authorization: `Bearer ${env.SUPABASE_KEY}`,
  'Content-Type': 'application/json',
};

async function sbRequest(method, path, body, extraHeaders) {
  return helpers.httpRequest({
    method,
    url: `${env.SUPABASE_URL}/rest/v1/${path}`,
    headers: { ...sbHeaders, ...(extraHeaders || {}) },
    body,
    json: true,
    timeout: 15000,
  });
}
async function sbInsert(path, body) { return sbRequest('POST', path, body, { Prefer: 'return=representation' }); }
async function sbPatch(path, body) { return sbRequest('PATCH', path, body, { Prefer: 'return=representation' }); }

// Sandbox mode: on when there's no real Meta token configured (the sandbox
// n8n instance is deliberately deployed without one, so it's structurally
// incapable of reaching real WhatsApp, not just told not to). Every outbound
// send is captured in `sandbox_outbound` instead, for the test webpage to
// display, and a fake message id/media id stands in for the real one. PDF
// rendering (Gotenberg) still runs for real in sandbox -- it's self-hosted,
// nothing leaves the server -- only the Meta upload/send steps are stubbed.
const SANDBOX = !env.META_TOKEN;
async function sandboxLog(toNumber, text, kind) {
  const messageId = `sandbox-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  try {
    await sbRequest('POST', 'sandbox_outbound', { to_number: toNumber, kind: kind || 'text', message_text: text, message_id: messageId });
  } catch (e) {}
  return messageId;
}

function sanitizeTemplateParam(text) {
  return String(text || '')
    .replace(/[\r\n]+/g, ' -- ')
    .replace(/\s{2,}/g, ' ')
    .trim()
    .slice(0, 1000) || '(see details)';
}

// Strips markdown formatting artifacts out of an LLM's free-text output
// before it ever reaches a WhatsApp send. See stage5-fanout-code.js's
// version for the full explanation -- owner's explicit, repeated rule is no
// "*" or "-" anywhere in this bot's messages, but nothing enforced that on
// LLM-generated free text (only ever applied to hand-written fixed
// strings). Hard backstop, not just a prompt ask.
function stripMarkdown(text) {
  return String(text || '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^[-*]\s+/gm, '')
    .replace(/`+/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
}

// WhatsApp rejects free-form text once 24h have passed since the recipient's
// last inbound message (error 131047) -- fall back to the approved
// "bali_update" utility template instead of the send just failing.
//
// Owner's explicit correction (2026-08-03): this used to stuff the ENTIRE
// message text into the template's one body variable, mangling the owner's
// own intentional message formats. shortLabel is now a short description
// instead (an event name, or a generic fallback) -- the real content always
// follows as a genuine, unmodified send in sendWhatsApp below.
async function sendWhatsAppTemplate(toNumber, shortLabel) {
  if (SANDBOX) return sandboxLog(toNumber, shortLabel, 'template');
  const res = await helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v20.0/${env.META_PHONE_ID}/messages`,
    headers: { Authorization: `Bearer ${env.META_TOKEN}`, 'Content-Type': 'application/json' },
    body: {
      messaging_product: 'whatsapp',
      to: toNumber,
      type: 'template',
      template: {
        name: 'bali_update',
        language: { code: 'en_US' },
        components: [{ type: 'body', parameters: [{ type: 'text', text: sanitizeTemplateParam(shortLabel) }] }],
      },
    },
    json: true,
    timeout: 20000,
  });
  return res?.messages?.[0]?.id || null;
}

// Confirmed live: a direct text send to a contact whose last inbound message
// was well over 24h old returned 200 with a real message id from Meta, but
// never actually delivered -- outside the messaging window, Meta accepts the
// call and silently drops it instead of rejecting it synchronously with
// 131047 (delivery failure only shows up later via a status webhook we don't
// listen for). Catching 131047 reactively therefore doesn't reliably work.
// Check the window proactively instead, from the contact's own last inbound
// message, and go straight to the template when it's closed.
// Set right before the action dispatcher at the bottom of this file, before
// any of these functions are actually called -- see the fix note inside
// isWithinMessagingWindow itself.
let CURRENT_INBOUND_SENDER = null;

async function isWithinMessagingWindow(toNumber) {
  // Same fix as stage1-code.js's version -- see that file for the full
  // explanation. Whoever just messaged us this exact execution is trivially
  // within-window right now regardless of what's in the DB yet, since their
  // inbound row for THIS message isn't logged until after the reply is
  // sent. handleLawyerInbound's from_number is a function parameter, not
  // visible here, hence the module-level CURRENT_INBOUND_SENDER instead.
  if (toNumber === CURRENT_INBOUND_SENDER) return true;
  const contacts = await sbRequest('GET', `contacts?phone_number=eq.${encodeURIComponent(toNumber)}&select=id`);
  const contactId = contacts[0]?.id;
  if (!contactId) return false;
  const rows = await sbRequest(
    'GET',
    `conversations?sender_contact_id=eq.${contactId}&direction=eq.inbound&select=created_at&order=created_at.desc&limit=1`
  );
  if (!rows[0]) return false;
  const hoursSinceLastInbound = (Date.now() - new Date(rows[0].created_at).getTime()) / (1000 * 60 * 60);
  return hoursSinceLastInbound < 23; // stay a safety margin under the real 24h cutoff
}

async function sendRawText(toNumber, text) {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v20.0/${env.META_PHONE_ID}/messages`,
    headers: { Authorization: `Bearer ${env.META_TOKEN}`, 'Content-Type': 'application/json' },
    body: { messaging_product: 'whatsapp', to: toNumber, type: 'text', text: { body: text } },
    json: true,
    timeout: 20000,
  });
  return res?.messages?.[0]?.id || null;
}

// Owner's explicit correction (2026-08-03): don't attempt the real content
// right behind the template anymore -- see stage1-code.js's version for the
// full explanation. Park it and wait for real proof the window's open
// (their next inbound message) instead.
async function queueMessage(toNumber, text) {
  await sbInsert('queued_messages', { phone_number: toNumber, message_text: text });
}

async function flushQueuedMessages(toNumber) {
  const queued = await sbRequest('GET', `queued_messages?phone_number=eq.${encodeURIComponent(toNumber)}&order=created_at.asc&select=*`);
  for (const row of queued) {
    await sendRawText(toNumber, row.message_text).catch(() => null);
    await sbRequest('DELETE', `queued_messages?id=eq.${row.id}`);
  }
}

// shortLabel: see sendWhatsAppTemplate above.
async function sendWhatsApp(toNumber, text, shortLabel) {
  if (SANDBOX) return sandboxLog(toNumber, text, 'text');
  if (!(await isWithinMessagingWindow(toNumber))) {
    await sendWhatsAppTemplate(toNumber, shortLabel || 'an update');
    await queueMessage(toNumber, text);
    return null;
  }
  try {
    return await sendRawText(toNumber, text);
  } catch (err) {
    let errStr;
    try { errStr = JSON.stringify(err, Object.getOwnPropertyNames(err)); } catch (e) { errStr = String(err); }
    errStr += JSON.stringify(err?.response?.data || err?.response?.body || '');
    if (errStr.includes('131047')) {
      await sendWhatsAppTemplate(toNumber, shortLabel || 'an update');
      await queueMessage(toNumber, text);
      return null;
    }
    throw err;
  }
}

async function sendWhatsAppDocument(toNumber, mediaId, filename, caption) {
  if (SANDBOX) return sandboxLog(toNumber, `[document] ${filename}${caption ? ': ' + caption : ''}`, 'document');
  const res = await helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v20.0/${env.META_PHONE_ID}/messages`,
    headers: { Authorization: `Bearer ${env.META_TOKEN}`, 'Content-Type': 'application/json' },
    body: {
      messaging_product: 'whatsapp',
      to: toNumber,
      type: 'document',
      document: { id: mediaId, filename, caption },
    },
    json: true,
    timeout: 20000,
  });
  return res?.messages?.[0]?.id || null;
}

// Same idea as sendWhatsAppDocument but type-generic (image or document) --
// duplicated from stage1-code.js's version (no shared module system in this
// codebase). Used where the sender might reasonably send either (e.g. a
// lawyer forwarding a photo of a signed page instead of a proper PDF scan --
// same real-world case already handled for the client's signed-contract
// upload in stage1-code.js).
async function sendWhatsAppMedia(toNumber, mediaType, mediaId, caption) {
  if (SANDBOX) return sandboxLog(toNumber, `[${mediaType}]${caption ? ' ' + caption : ''}`, mediaType);
  const res = await helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v20.0/${env.META_PHONE_ID}/messages`,
    headers: { Authorization: `Bearer ${env.META_TOKEN}`, 'Content-Type': 'application/json' },
    body: {
      messaging_product: 'whatsapp',
      to: toNumber,
      type: mediaType,
      [mediaType]: { id: mediaId, caption },
    },
    json: true,
    timeout: 20000,
  });
  return res?.messages?.[0]?.id || null;
}

// Renders invoice HTML (styled to match the real BALI-2026-003 template) to a
// PDF Buffer. Goes through a small internal sub-workflow (Webhook -> Code
// [prepareBinaryData] -> HTTP Request -> Respond to Webhook) instead of
// calling Gotenberg directly from this Code node -- confirmed live that this
// n8n version's Code-node `helpers.httpRequest` cannot correctly send
// multipart/form-data (every construction attempt either sent 0 bytes,
// mangled the buffer into something ~100x larger than intended, or got the
// Content-Type/boundary wrong -- verified via Gotenberg's own server logs,
// not guesswork). The dedicated HTTP Request node has mature native
// multipart/binary support and is confirmed working. See the "Render PDF"
// node chain in this workflow (Webhook path `bali-render-pdf`).
async function renderPdf(html) {
  return helpers.httpRequest({
    method: 'POST',
    url: `${env.N8N_BASE_URL}/webhook/bali-render-pdf`,
    body: { html },
    json: true,
    encoding: 'arraybuffer',
    timeout: 30000,
  });
}

// Uploads a PDF buffer to Meta's media library so it can be attached to a
// WhatsApp document message. Returns the media id. Same reason as renderPdf:
// goes through a dedicated HTTP Request node sub-workflow (Webhook ->
// prepareBinaryData -> HTTP Request -> Respond) instead of a direct
// helpers.httpRequest formData call, which is confirmed broken in this
// n8n version for multipart uploads.
async function uploadWhatsAppMedia(pdfBuffer, filename) {
  if (SANDBOX) return `sandbox-media-${filename}`;
  const buf = Buffer.isBuffer(pdfBuffer) ? pdfBuffer : Buffer.from(pdfBuffer);
  const res = await helpers.httpRequest({
    method: 'POST',
    url: `${env.N8N_BASE_URL}/webhook/bali-upload-media`,
    body: { pdfBase64: buf.toString('base64'), filename },
    json: true,
    timeout: 30000,
  });
  return res?.id || null;
}

async function askOpenAIJson(systemPrompt, userText, temperature) {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: { Authorization: `Bearer ${env.OPENAI_KEY}`, 'Content-Type': 'application/json' },
    body: {
      model: 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      ...(temperature !== undefined ? { temperature } : {}),
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userText || '' },
      ],
    },
    json: true,
    timeout: 30000,
  });
  try {
    return JSON.parse(res.choices[0].message.content);
  } catch (e) {
    return null;
  }
}

async function findPm() { return (await sbRequest('GET', 'contacts?role=eq.pm&select=*&limit=1'))[0] || null; }
async function findLawyer() { return (await sbRequest('GET', 'contacts?role=eq.lawyer&select=*&limit=1'))[0] || null; }
async function getBooking(id) { return (await sbRequest('GET', `bookings?id=eq.${id}&select=*`))[0] || null; }
async function getContact(id) { return (await sbRequest('GET', `contacts?id=eq.${id}&select=*`))[0] || null; }

async function logConversation(bookingId, senderContactId, direction, text, stage) {
  await sbInsert('conversations', [{ booking_id: bookingId, sender_contact_id: senderContactId, direction, message_text: text, stage }]);
}

async function askPmDirectly(bookingId, fieldName, questionText, shortLabel) {
  const pm = await findPm();
  if (!pm) return null;
  const pending = (await sbInsert('pending_questions', { booking_id: bookingId, field_name: fieldName, question_text: questionText }))[0];
  const msgId = await sendWhatsApp(pm.phone_number, questionText, shortLabel);
  if (msgId) await sbPatch(`pending_questions?id=eq.${pending.id}`, { whatsapp_message_id: msgId });
  return pending;
}

function formatMoney(n) {
  return 'N' + Number(n || 0).toLocaleString('en-NG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatDatePdf(d) {
  return new Date(d).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
}

function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// Styled to match the real BALI-2026-003 reference invoice: gold wordmark top
// left, dark table header, red WHT deduction, twin payment-info/terms boxes.
function formatInvoiceHtml(inv, booking) {
  const rows = (inv.line_items || []).map((li) => `
    <tr>
      <td class="desc">${escapeHtml(li.description)}</td>
      <td class="amt">${formatMoney(li.amount)}</td>
    </tr>`).join('');

  return `<!DOCTYPE html>
