    <tr>
      <td class="desc">${escapeHtml(li.description)}</td>
      <td class="amt">${formatMoney(li.amount)}</td>
    </tr>`).join('');

  return `<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
