  .box p { margin: 3px 0; }
  .footer { text-align: center; color: #9CA3AF; font-size: 10px; margin-top: 32px; }
</style></head>
<body>
  <div class="header">
    <div>
      <div class="logo"><img src="data:image/png;base64," alt="Bali" /></div>
      <div class="company">BALI RECREATION CENTER LIMITED</div>
